class Bank {
}

class Customer {
  + Name : string
  + Address : string
}

class Account {
  + Balance : double
}

class SavingsAccount extends Account {
  + InterestRate : float
}

class InvestmentAccount extends Account {
}

class Stock {
  + Ticker : string
}

class StockOrder {
  + Quantity : int
  + Price : double
  + Commission : double
}

Bank "1" -- "*" Customer
Customer "1" -- "*" Account
Account "1" -- "0..*" StockOrder
StockOrder "0..*" -- "1" Stock
InvestmentAccount "1" -- "0..*" StockOrder

@enduml

